/// The Amalfi text styles: Inter for the interface, JetBrains Mono for
/// monospaced text, both served by this package.
///
/// Each style is a [TextStyle] factory (`AmalfiType.body(color: …)`) and a
/// token with its raw values (`AmalfiType.bodyToken`).
abstract final class AmalfiType {
  /// `Display`: Inter 34/40, weight 700.
  static const AmalfiTextToken displayToken = AmalfiTextToken(
    name: 'Display',
    family: 'Inter',
    size: 34,
    lineHeight: 40,
    weight: FontWeight.w700,
    colorTokens: [
      'Text/Primary',
      'Text/Secondary',
      'Text/Tertiary',
      'Text/On Accent',
      'Accent/Amalfi',
    ],
  );

  /// `Display` in [color] (none: inherited).
  static TextStyle display({Color? color}) => displayToken.style(color: color);

  /// `Title 1`: Inter 26/32, weight 700.
