  /// `Numeral 64`: Inter 64/natural, weight 400. Use: Clock app large digits
  /// (dark appearance).
  static const AmalfiTextToken numeral64Token = AmalfiTextToken(
    name: 'Numeral 64',
    family: 'Inter',
    size: 64,
    lineHeight: null,
    weight: FontWeight.w400,
    colorTokens: ['Text/Primary', 'Text/Tertiary'],
  );

  /// `Numeral 64` in [color] (none: inherited).
  static TextStyle numeral64({Color? color}) =>
      numeral64Token.style(color: color);

  /// `Numeral 72`: Inter 72/natural, weight 400. Use: Clock app large digits
  /// (dark appearance).
  static const AmalfiTextToken numeral72Token = AmalfiTextToken(
    name: 'Numeral 72',
    family: 'Inter',
    size: 72,
    lineHeight: null,
    weight: FontWeight.w400,
    colorTokens: ['Text/Primary', 'Text/Tertiary'],
  );

  /// `Numeral 72` in [color] (none: inherited).
  static TextStyle numeral72({Color? color}) =>
      numeral72Token.style(color: color);

  /// `Numeral 104`: Inter 104/natural, weight 400. Use: Clock app large digits
  /// (dark appearance).
  static const AmalfiTextToken numeral104Token = AmalfiTextToken(
    name: 'Numeral 104',
    family: 'Inter',
    size: 104,
    lineHeight: null,
    weight: FontWeight.w400,
    colorTokens: ['Text/Primary', 'Text/Tertiary'],
  );

  /// `Numeral 104` in [color] (none: inherited).
  static TextStyle numeral104({Color? color}) =>
      numeral104Token.style(color: color);

  /// `Wordmark`: Inter 110/natural, weight 700. Use: kit cover only, not UI.
  static const AmalfiTextToken wordmarkToken = AmalfiTextToken(
    name: 'Wordmark',
    family: 'Inter',
    size: 110,
    lineHeight: null,
    weight: FontWeight.w700,
    colorTokens: ['Text/On Accent'],
  );

  /// `Wordmark` in [color] (none: inherited).
  static TextStyle wordmark({Color? color}) =>
      wordmarkToken.style(color: color);

  /// Every text style token, in the order of `tokens.json`.
  static const List<AmalfiTextToken> tokens = [
    displayToken,
    title1Token,
    title2Token,
    title3Token,
    headlineToken,
    bodyToken,
    bodyEmphasisToken,
    sidebarToken,
    sidebarHeaderToken,
    calloutToken,
    labelToken,
    captionToken,
    monoToken,
    fieldToken,
    numeral40Token,
    numeral64Token,
    numeral72Token,
    numeral104Token,
    wordmarkToken,
  ];

  /// The token of the style named [name] (`Title 1`); null when there is none.
  static AmalfiTextToken? tokenNamed(String name) => switch (name) {
    'Display' => displayToken,
    'Title 1' => title1Token,
    'Title 2' => title2Token,
    'Title 3' => title3Token,
    'Headline' => headlineToken,
    'Body' => bodyToken,
    'Body Emphasis' => bodyEmphasisToken,
    'Sidebar' => sidebarToken,
    'Sidebar Header' => sidebarHeaderToken,
    'Callout' => calloutToken,
    'Label' => labelToken,
    'Caption' => captionToken,
    'Mono' => monoToken,
    'Field' => fieldToken,
    'Numeral 40' => numeral40Token,
    'Numeral 64' => numeral64Token,
    'Numeral 72' => numeral72Token,
    'Numeral 104' => numeral104Token,
    'Wordmark' => wordmarkToken,
    _ => null,
  };

  /// The style named [name] in [color]; null when there is none.
  static TextStyle? byName(String name, {Color? color}) =>
      tokenNamed(name)?.style(color: color);
}

/// The layout grid.
abstract final class AmalfiGrid {
  /// The grid step in points: every frame x, y, width, height is a multiple of
  /// 4; no half points; text frames on whole points.
  static const double base = 4;

  /// [value] rounded to the nearest multiple of [base].
  static double snap(double value) => (value / base).roundToDouble() * base;
}

/// Spacing steps and the padding of windows and panels, in points.
abstract final class AmalfiSpacing {
  /// `spacing.xs`.
  static const double xs = 4;

  /// `spacing.s`.
  static const double s = 8;

  /// `spacing.m`.
  static const double m = 12;

  /// `spacing.l`.
  static const double l = 16;

  /// `spacing.xl`.
  static const double xl = 20;

  /// `spacing.xxl`.
  static const double xxl = 24;

  /// `spacing.padding.regularWindow`.
  static const double paddingRegularWindow = 20;

  /// `spacing.padding.compactWindowAndPanel`.
  static const double paddingCompactWindowAndPanel = 16;

  /// `spacing.padding.documentAndSettings`.
  static const double paddingDocumentAndSettings = 24;
}

/// The one control scale of Amalfi: height and icon size of every control.
///
/// One scale for every control; toolbar items are 36 (user decision 2026-10-17,
/// macOS capsules are 38); never resize a control inside a bar.
///
/// Icon sizes: user decision 2026-10-17: Amalfi symbols draw ink = size x
/// 20/24, so a 20 pt symbol draws ~17 pt like macOS; never smaller. Icons are
/// set in the Silica Symbols font (silica-icons fonts/): font size = icon size.
enum AmalfiControlSize {
  /// `mini`: 20 pt high, 14 pt icons.
  mini(height: 20, iconSize: 14),

  /// `small`: 24 pt high, 16 pt icons.
  small(height: 24, iconSize: 16),

  /// `regular`: 28 pt high, 20 pt icons.
  regular(height: 28, iconSize: 20),

  /// `large`: 32 pt high, 20 pt icons.
  large(height: 32, iconSize: 20);

  const AmalfiControlSize({required this.height, required this.iconSize});

  /// The control height in points.
  final double height;

  /// The size of an icon inside the control, in points.
  final double iconSize;
}

/// Control heights that are not a control size (`controlHeights`).
abstract final class AmalfiControlHeights {
  /// `controlHeights.toolbar`, in points.
  static const double toolbar = 36;
}

/// Control icon sizes that are not a control size (`controlIcons`).
abstract final class AmalfiControlIcons {
  /// `controlIcons.toolbar`, in points.
  static const double toolbar = 20;

  /// `controlIcons.accessory`, in points.
  static const double accessory = 16;

  /// `controlIcons.menuBar`, in points.
  static const double menuBar = 20;

  /// `controlIcons.sidebar`, in points.
  static const double sidebar = 20;

  /// `controlIcons.list`, in points.
  static const double list = 20;
}

/// Corner radii, in points. Corners are smooth (continuous), smoothing 0.6, on
/// every rounded surface: draw them with `AmalfiSmoothBorder` (smoothing
/// [smoothing]).
abstract final class AmalfiRadii {
  /// The smoothing of every rounded corner (0: circular arcs).
  static const double smoothing = 0.6;

  /// `smallControl`.
  static const double smallControl = 7;

  /// `regularControl`.
  static const double regularControl = 9;

  /// `field`.
  static const double field = 9;

  /// `menu`.
  static const double menu = 12;

  /// `popover`.
  static const double popover = 16;

  /// `sheetAlert`.
  static const double sheetAlert = 20;

  /// `window`.
  static const double window = 18;

  /// `sidebarInsetPanel`.
  static const double sidebarInsetPanel = 14;

  /// `faroAndLauncher`.
  static const double faroAndLauncher = 28;

  /// `capsule`: half the [height] of the shape.
  static double capsule(double height) => height / 2;
}

/// The drop shadows of one appearance, by elevation level.
final class AmalfiShadows {
  const AmalfiShadows._({
    required this.brightness,
    required this.level1,
    required this.level2,
    required this.level3,
  });

  /// The appearance of these shadows.
  final Brightness brightness;

  /// Level 1: small raised controls (switch thumb, slider thumb, secondary push
  /// button).
  final List<BoxShadow> level1;

  /// Level 2: Glass/Regular objects (Dock, toolbar controls, banners, HUDs).
  final List<BoxShadow> level2;

  /// Level 3: windows, menus, popovers, Faro, sheets (Glass/Thick and windows).
  final List<BoxShadow> level3;

  /// The light appearance.
  static const AmalfiShadows light = AmalfiShadows._(
    brightness: Brightness.light,
    level1: [
      BoxShadow(color: Color(0x1A000000), offset: Offset(0, 1), blurRadius: 2),
    ],
    level2: [
      BoxShadow(color: Color(0x1F000000), offset: Offset(0, 4), blurRadius: 12),
    ],
    level3: [
      BoxShadow(
        color: Color(0x2E000000),
        offset: Offset(0, 12),
        blurRadius: 32,
      ),
    ],
  );

  /// The dark appearance.
  static const AmalfiShadows dark = AmalfiShadows._(
    brightness: Brightness.dark,
    level1: [
      BoxShadow(color: Color(0x33000000), offset: Offset(0, 1), blurRadius: 2),
    ],
    level2: [
      BoxShadow(color: Color(0x52000000), offset: Offset(0, 4), blurRadius: 12),
    ],
    level3: [
      BoxShadow(
        color: Color(0x5C000000),
        offset: Offset(0, 12),
        blurRadius: 32,
      ),
    ],
  );

  /// The shadows of [brightness].
  static AmalfiShadows of(Brightness brightness) => switch (brightness) {
    Brightness.light => light,
    Brightness.dark => dark,
  };

  /// The shadow of [level]; null when there is no such level.
  List<BoxShadow>? level(int level) => switch (level) {
    1 => level1,
    2 => level2,
    3 => level3,
    _ => null,
  };
}

/// The keyboard focus halo, drawn as wide as [halo]; it follows the control
/// radius, outside the control.
abstract final class AmalfiFocus {
  /// The halo width in points.
  static const double halo = 3;

  /// The colour token of the halo.
  static const String colorToken = 'Line/Focus';

  /// The halo colour in [colors] (`Line/Focus`).
  static Color color(AmalfiColors colors) => colors.lineFocus;
}

/// Interaction states: overlays drawn over a control, and the disabled look.
abstract final class AmalfiStates {
  /// `hoverOverlay`: light `#FFFFFF29`, dark `#FFFFFF1F`.
  static Color hoverOverlay(Brightness brightness) => switch (brightness) {
    Brightness.light => Color(0x29FFFFFF),
    Brightness.dark => Color(0x1FFFFFFF),
  };

  /// `pressOverlay`: light `#00000024`, dark `#00000040`.
  static Color pressOverlay(Brightness brightness) => switch (brightness) {
    Brightness.light => Color(0x24000000),
    Brightness.dark => Color(0x40000000),
  };

  /// The opacity of a disabled control: whole control at 35 % opacity, no
  /// hover/press; a select-one segmented control keeps its selection visible
  /// (dimmed with the rest).
  static const double disabledOpacity = 0.35;
}

