  static const double thumbInset = 2;

  /// How far a pressed thumb stretches toward the middle, in points.
  static const double pressedStretch = 4;

  /// How far the lens reaches beyond the thumb at the `mini` size, in points
  /// (`switch.lens.mini`).
  static const double lensMini = 8;

  /// How far the lens reaches beyond the thumb at the `small` size, in points
  /// (`switch.lens.small`).
  static const double lensSmall = 8;

  /// How far the lens reaches beyond the thumb at the `regular` size, in points
  /// (`switch.lens.regular`).
  static const double lensRegular = 12;
}

/// The easing curves of the fade tokens (`motion.md`).
abstract final class AmalfiCurves {
  /// `ease-out` (0.2, 0, 0, 1).
  static const Cubic easeOut = Cubic(0.2, 0, 0, 1);

  /// `ease-in-out` (0.4, 0, 0.2, 1).
  static const Cubic easeInOut = Cubic(0.4, 0, 0.2, 1);
}

/// The spring tokens (`motion.md`), as [SpringDescription]s of mass 1.
///
/// Reduced motion: springs become `AmalfiFades.quick` cross-fades, with no
/// overshoot and no scale; bounces are off.
abstract final class AmalfiSprings {
  /// `spring.snappy`: overshoot ~0 %. Use: hover/press, lens grow, switch
  /// thumb, checkbox.
  static const AmalfiSpring snappy = AmalfiSpring(
    name: 'spring.snappy',
    response: 0.25,
    dampingRatio: 0.9,
    stiffness: 631.7,
    damping: 45.2,
  );

  /// `spring.panel`: overshoot ~1–2 % (+2 pt on a 270 pt growth). Use: Faro
  /// results growth, menus and popovers height, sheets.
  static const AmalfiSpring panel = AmalfiSpring(
    name: 'spring.panel',
    response: 0.35,
    dampingRatio: 0.82,
    stiffness: 322.3,
    damping: 29.4,
  );

  /// `spring.window`: overshoot <1 %. Use: window open/close scale, minimise,
  /// Mission Control layouts.
  static const AmalfiSpring window = AmalfiSpring(
    name: 'spring.window',
    response: 0.4,
    dampingRatio: 0.88,
    stiffness: 246.7,
    damping: 27.6,
  );

  /// `spring.morph`: overshoot ~4–5 %. Use: shape morphs: Faro buttons out/in,
  /// Launcher ↔ Faro, Control Center detail expand.
  static const AmalfiSpring morph = AmalfiSpring(
    name: 'spring.morph',
    response: 0.5,
    dampingRatio: 0.7,
    stiffness: 157.9,
    damping: 17.6,
  );

  /// `spring.bouncy`: overshoot ~16 %. Use: Dock launch bounce, attention
  /// bounce.
  static const AmalfiSpring bouncy = AmalfiSpring(
    name: 'spring.bouncy',
    response: 0.6,
    dampingRatio: 0.5,
    stiffness: 109.7,
    damping: 10.5,
  );
}

/// The fade tokens (`motion.md`).
abstract final class AmalfiFades {
  /// `fade.instant`: 100 ms, ease-out. Use: closing transient surfaces (Faro,
  /// menus, tooltips).
  static const AmalfiFade instant = AmalfiFade(
    name: 'fade.instant',
    duration: Duration(milliseconds: 100),
    curve: AmalfiCurves.easeOut,
  );

  /// `fade.quick`: 150 ms, ease-out. Use: content swaps inside a panel, hover
  /// overlays.
  static const AmalfiFade quick = AmalfiFade(
    name: 'fade.quick',
    duration: Duration(milliseconds: 150),
    curve: AmalfiCurves.easeOut,
  );

  /// `fade.standard`: 250 ms, ease-in-out. Use: notifications in/out,
  /// appearance changes.
  static const AmalfiFade standard = AmalfiFade(
    name: 'fade.standard',
    duration: Duration(milliseconds: 250),
    curve: AmalfiCurves.easeInOut,
  );

  /// `fade.slow`: 400 ms, ease-in-out. Use: wallpaper, display changes.
  static const AmalfiFade slow = AmalfiFade(
    name: 'fade.slow',
    duration: Duration(milliseconds: 400),
    curve: AmalfiCurves.easeInOut,
  );
}

/// The delay tokens (`motion.md`).
abstract final class AmalfiDelays {
  /// `delay.hoverIntent`: 60 ms. Use: pointer-enter morphs (Faro buttons).
  static const Duration hoverIntent = Duration(milliseconds: 60);

  /// `delay.tooltip`: the first one. Use: tooltips.
  static const Duration tooltip = Duration(milliseconds: 700);

  /// `delay.tooltip` while the pointer moves between items.
  static const Duration tooltipWhileMoving = Duration(milliseconds: 0);
}
